def _doc(path: Path, paras: list[str], title: str) -> None:
    doc = Document()
    C.set_east_asian_font(doc)
    C.fix_core(doc, title, FEAT)
    for t in paras:
        if t == "TABLE":
            tb = doc.add_table(rows=len(SCORE), cols=3)
            tb.style = "Table Grid"
            for i, row in enumerate(SCORE):
                for j, v in enumerate(row):
                    tb.cell(i, j).text = v
        else:
            doc.add_paragraph(t)
    doc.save(path)


def build(root: Path) -> None:
    d = root / CASE
    d.mkdir(parents=True, exist_ok=True)
    _doc(d / "招标文件.docx", ZHAOBIAO, "招标文件")
    _doc(d / "补充通知.docx", BUCHONG, "补充通知")
